#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    string s;
    cin >> s;
    vector<vector<long long>> pairs(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> pairs[i][j];
        }
    }

    parent.resize(n);
    sizes.assign(n, 1);
    for (int v = 0; v < n; v++) parent[v] = v;
    for (const vector<long long>& p : pairs) unite((int)p[0] - 1, (int)p[1] - 1);
    map<int, vector<int>> groups;
    for (int i = 0; i < n; i++) groups[findRoot(i)].push_back(i);
    string result = s;
    for (auto& entry : groups) {
        string letters;
        for (int i : entry.second) letters += s[i];
        sort(letters.begin(), letters.end());
        for (size_t k = 0; k < entry.second.size(); k++) result[entry.second[k]] = letters[k];
    }
    cout << result << "\n";

    return 0;
}

