import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        String s = next();
        long[][] pairs = new long[(int) m][2];
        for (int i = 0; i < pairs.length; i++) {
            for (int j = 0; j < pairs[i].length; j++) {
                pairs[i][j] = Long.parseLong(next());
            }
        }

        int length = (int) n;
        parent = new int[length];
        sizes = new int[length];
        for (int v = 0; v < length; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        for (long[] p : pairs) unite((int) p[0] - 1, (int) p[1] - 1);
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < length; i++) groups.computeIfAbsent(findRoot(i), k -> new ArrayList<>()).add(i);
        char[] result = s.toCharArray();
        for (List<Integer> positions : groups.values()) {
            char[] letters = new char[positions.size()];
            for (int k = 0; k < positions.size(); k++) letters[k] = s.charAt(positions.get(k));
            Arrays.sort(letters);
            for (int k = 0; k < positions.size(); k++) result[positions.get(k)] = letters[k];
        }
        System.out.println(new String(result));
    }
}
